def countMinCombos(coins, amount):
    MOD = 1000000007
    INF = float("inf")
    best = [INF] * (amount + 1)
    ways = [0] * (amount + 1)
    best[0] = 0
    ways[0] = 1
    for c in coins:
        for s in range(c, amount + 1):
            cand = best[s - c] + 1
            if cand < best[s]:
                best[s] = cand
                ways[s] = ways[s - c]
            elif cand == best[s]:
                ways[s] = (ways[s] + ways[s - c]) % MOD
    return -1 if best[amount] == INF else ways[amount]
